// base definition for custom roles
const customRole = {
  id: "",
  name: "",
  image: "",
  ability: "",
  edition: "custom",
  firstNight: 0,
  firstNightReminder: "",
  otherNight: 0,
  otherNightReminder: "",
  reminders: [],
  remindersGlobal: [],
  setup: false,
  team: "townsfolk",
  isCustom: true,
};

export default new Vuex.Store({
  modules: {
    players,
    session,
    loginbackend,
  },
  state: {
    grimoire: {
      isNight: false,
      isNightOrder: true,
      isPublic: true,
      isMenuOpen: false,
      isStatic: false,
      isMuted: false,
      isImageOptIn: true,
      zoom: 0,
      background: "",
    },
    modals: {
      edition: false,
      fabled: false,
      gameState: false,
      nightOrder: false,
      reference: false,
      reminder: false,
      role: false,
      roles: false,
      voteHistory: false,
    },
    edition: editionJSONbyId.get("tb"),
    roles: getRolesByEdition(),
    otherTravelers: getTravelersNotInEdition(),
    fabled,
    jinxes,
  },
  getters: {
    /**
     * Return all custom roles, with default values and non-essential data stripped.
     * Role object keys will be replaced with a numerical index to conserve bandwidth.
     * @param roles
     * @returns {[]}
     */
    customRolesStripped: ({ roles }) => {
      const customRoles = [];
      const customKeys = Object.keys(customRole);
      const strippedProps = [
        "firstNightReminder",
        "otherNightReminder",
        "isCustom",
      ];
      roles.forEach((role) => {
        if (!role.isCustom) {
          customRoles.push({ id: role.id });
        } else {
          const strippedRole = {};
          for (let prop in role) {
            if (strippedProps.includes(prop)) {
              continue;
            }
            const value = role[prop];
            if (customKeys.includes(prop) && value !== customRole[prop]) {
              strippedRole[customKeys.indexOf(prop)] = value;
            }
          }
          customRoles.push(strippedRole);
        }
      });
      return customRoles;
    },
    rolesJSONbyId: () => rolesJSONbyId,
  },
  mutations: {
    setZoom: set("zoom"),
    setBackground: set("background"),
    toggleMuted: toggle("isMuted"),
    toggleMenu: toggle("isMenuOpen"),
    toggleNightOrder: toggle("isNightOrder"),
    toggleStatic: toggle("isStatic"),
    toggleNight: toggle("isNight"),
    toggleGrimoire: toggle("isPublic"),
    toggleImageOptIn: toggle("isImageOptIn"),
    toggleModal({ modals }, name) {
      if (name) {
        modals[name] = !modals[name];
      }
      for (let modal in modals) {
        if (modal === name) continue;
        modals[modal] = false;
      }
    },
    update_claim(state) {
      for(let a = 0; a < state.players.length; a++){
          if (state.players[a].id == state.loginbackend.playerId) {
            this.$store.commit("claimSeat", a);
            return;
          }
      }
      this.$store.commit("claimSeat", -1);
    },
    /**
     * Store custom roles
     * @param state
     * @param roles Array of role IDs or full role definitions
     */
    setCustomRoles(state, roles) {
      const processedRoles = roles
        // replace numerical role object keys with matching key names
        .map((role) => {
          if (role[0]) {
            const customKeys = Object.keys(customRole);
            const mappedRole = {};
            for (let prop in role) {
              if (customKeys[prop]) {
                mappedRole[customKeys[prop]] = role[prop];
              }
            }
            return mappedRole;
          } else {
            return role;
          }
        })
        // clean up role.id
        .map((role) => {
          role.id = clean(role.id);
          return role;
        })
        // map existing roles to base definition or pre-populate custom roles to ensure all properties
        .map(
          (role) =>
            rolesJSONbyId.get(role.id) ||
            state.roles.get(role.id) ||
            Object.assign({}, customRole, role),
        )
        // default empty icons and placeholders, clean up firstNight / otherNight
        .map((role) => {
          if (rolesJSONbyId.get(role.id)) return role;
          role.imageAlt = // map team to generic icon
            {
              townsfolk: "good",
              outsider: "outsider",
              minion: "minion",
              demon: "evil",
              fabled: "fabled",
            }[role.team] || "custom";
          role.firstNight = Math.abs(role.firstNight);
          role.otherNight = Math.abs(role.otherNight);
          return role;
        })
        // filter out roles that don't match an existing role and also don't have name/ability/team
        .filter((role) => role.name && role.ability && role.team)
        // sort by team
        .sort((a, b) => b.team.localeCompare(a.team));
      // convert to Map without Fabled
      state.roles = new Map(
        processedRoles
          .filter((role) => role.team !== "fabled")
          .map((role) => [role.id, role]),
      );
      // update Fabled to include custom Fabled from this script
      state.fabled = new Map([
        ...processedRoles
          .filter((r) => r.team === "fabled")
          .map((r) => [r.id, r]),
        ...fabledJSON.map((role) => [role.id, role]),
      ]);
      // update extraTravelers map to only show travelers not in this script
      state.otherTravelers = new Map(
        rolesJSON
          .filter(
            (r) => r.team === "traveler" && !roles.some((i) => i.id === r.id),
          )
          .map((role) => [role.id, role]),
      );
    },
    setEdition(state, edition) {
      if (editionJSONbyId.has(edition.id)) {
        state.edition = editionJSONbyId.get(edition.id);
        state.roles = getRolesByEdition(state.edition);
        state.otherTravelers = getTravelersNotInEdition(state.edition);
      } else {
        state.edition = edition;
      }
      state.modals.edition = false;
    },
  },
  plugins: [persistence, socket],
});

const CommandPacket = require('./packet.js');

class LiveSession {
  constructor(store) {
    // this._wss = "wss://clocktower1:8080/";
    //this._wss = "ws://localhost:8081/"; // uncomment if using local server with NODE_ENV=development
    this._socket = null;
    this._isSpectator = true;
    this._gamestate = [];
    this._store = store;
    this._pingInterval = 30 * 1000; // 30 seconds between pings
    this._pingTimer = null;
    this._reconnectTimer = null;
    this._players = {}; // map of players connected to a session
    this._pings = {}; // map of player IDs to ping
    // reconnect to previous session
  }

  /**
   * Open a new session for the passed channel.
   * @param channel
   * @private
   */
    login(usrname, pwd) {
      this._wss = this._store.state.loginbackend.backendServer;

      this._socket = new WebSocket(
        this._wss + "login",
      );

      this._socket.addEventListener("message", this._handlePacket.bind(this));

      console.log("login with",usrname, pwd);

      // 设置连接超时（单位：毫秒）
      const timeoutDuration = 5000;
      let timeoutHandle = setTimeout(() => {
          if (this._socket && this._socket.readyState !== WebSocket.OPEN) {
            alert("无法连接到服务器。检查你的区服号，或服务器状态异常。");
            this._socket.close();
            this._socket = null;
            this._store.commit("loginbackend/resetServerURL");
          }
      }, timeoutDuration);

      const onOpenL = () =>{
        clearTimeout(timeoutHandle); // 连接成功，取消超时计时器

        const cmd = new CommandPacket("login");
        if(usrname != ''){
          cmd.addCommand("login",{
            username: usrname,
            password: pwd,
          });

        }else{
          cmd.addCommand("token",{
            token: pwd,
          });
        }
        this._sendPacket(cmd);

      }
      this._socket.onopen = onOpenL.bind(this);

      this._socket.onclose = (err) => {
        this._socket = null;
        clearInterval(this._pingTimer);
        this._pingTimer = null;
        if (err.code !== 1000) {
          this._store.dispatch("loginbackend/logout");
          //this._store.commit("loginbackend/setSessionId", "");
          //this._store.commit("loginbackend/setPlayerId", "");
          if (err.reason) alert(err.reason);
        }
      };

      this._socket.onerror = () => {
        alert("服务器状态异常。");
        this._socket = null;
        if (this._pingTimer) {
          clearInterval(this._pingTimer);
          this._pingTimer = null;
        }
        // 可选：触发退出登录或提示
        this._store.commit("loginbackend/resetServerURL");
      };

    }

  /**
   * Send a message through the socket.
   * @param command
   * @param params
   * @private
   */
  _send(command, params) {
    const sessionId = this._store.state.loginbackend.sessionId;
    const senderId = this._store.state.loginbackend.playerId;
    if (this._socket && this._socket.readyState == 1) {
      const packetx = new CommandPacket("boardcast", sessionId);
      packetx.sender = senderId;
      packetx.addCommand(command, params);
      this._sendPacket(packetx);
    }
  }

  /**
   * Send a message directly to a single playerId, if provided.
   * Otherwise broadcast it.
   * @param playerId player ID or "host", optional
   * @param command
   * @param params
   * @private
   */
  _sendDirect(playerId, command, params) {
    if (playerId) {
      const sessionId = this._store.state.loginbackend.sessionId;
      const senderId = this._store.state.loginbackend.playerId;
      if (this._socket && this._socket.readyState == 1) {
        const packetx = new CommandPacket("direct", sessionId);
        packetx.sender = senderId;
        packetx.receiver = playerId;
        packetx.addCommand(command, params);
        this._sendPacket(packetx);
      }
    } else {
      this._send(command, params);
    }
  }

  _handlePacket(rawevt) {
    console.log("raw:", rawevt.data);
    const packet = CommandPacket.deserialize(rawevt.data);
    switch(packet.header) {
      case 'login':
        packet.forEachCommand(this._handleLogin.bind(this));
        return;
      case 'sessionset':
        packet.forEachCommand(this._handleSession.bind(this));
        return;
      case 'require':
        packet.forEachCommand(this._handleRequire.bind(this));
        return;
      case 'sync':
        packet.forEachCommand(this._handleSync.bind(this));
        return;
      default:
        packet.forEachCommand(this._handleMessage.bind(this));
    }
  }

  _handleLogin(packet, command, params){
          switch (command) {
            case "success":  
              this._store.commit("loginbackend/setPlayerId", params['token']);
              break;
            case "failed":
              alert("Username or password incorrect.");
              break;
            case "session_restore":
              alert("You come back to previous session.");
              this._store.dispatch("loginbackend/joinSession", {sessionId: params});
              //this._store.commit("loginbackend/setSessionId", param);
              break;
          }

  }

  _handleSession(packet, command, params) {
      switch (command) {
        case 'state':
          if(params == 'host') {
            this._isSpectator = false;
            this._store.commit("session/setSpectator", false);
            this.sendGamestate();
            alert("You are the host.");
            break;
          }else{
            this._isSpectator = true;
            this._store.commit("session/setSpectator", true);
            this._sendDirect(
                "host",
                "getGamestate",
                this._store.state.loginbackend.playerId,
              );
            alert("You are the player.");

            const autocom = new CommandPacket("sessionset");
            autocom.addCommand("autoclaim");
            this._sendPacket(autocom)

            break;
          }
        // case 'seatinfo':
        //   console.log("updating seat");
        //   // remove previous seat
        //   this._store.commit("players/update_seat", {
        //       index: params.seatid,
        //       property: 'id',
        //       value: params.playerId,
        //   });
        //   this._store.commit("players/update_seat", {
        //       index: params.seatid,
        //       property: 'name',
        //       value: params.username,
        //   });
        //   break;
        case 'reset':
          console.log("This is a new game.");
          this._store.commit("players/clear");
          break;
      }
  }
  /**
   * Yan_ice: mark.
   * Handle an incoming socket message.
   * @param data
   * @private
   */
  _handleRequire(packet, command, params) {
    switch(command){
      case 'leave_session':
        alert(params);
        this._store.dispatch("loginbackend/leaveSession");
        break;
      case 'logout':
        alert(params);
        this.disconnect();
        break;
      case 'prepare_seat': // prepare a seat for user
        {
          const playersls = this._store.state.players.players;
          if(playersls.some((player) => player.id == params.token)) {
            return;
          }

          for (let i = 0; i < playersls.length; i++) {
            const player = playersls[i];
            if (player.id == '') {
              this._store.commit("players/update", {
                player,
                property: "id",
                value: params.token,
              });
              this._store.commit("players/update", {
                player,
                property: "name",
                value: params.username,
              });
              this._store.commit("players/update_claim");
              return;
            }
          }

          this._store.commit("players/add");
          const player = playersls[playersls.length-1];
          this._store.commit("players/update", {
                player,
                property: "id",
                value: params.token,
          });
          this._store.commit("players/update", {
                player,
                property: "name",
                value: params.username,
          });
          this._store.commit("players/update_claim");
          break;
        }
      case 'clean_seat':
        {
          const playersls = this._store.state.players.players;
          for (let i = 0; i < playersls.length; i++) {
            const player = playersls[i];
            if (player.id == params) {
              this._store.commit("players/update", {
                player,
                property: "id",
                value: '',
              });
              this._store.commit("players/update", {
                    player,
                    property: "name",
                    value: '---',
              });
            }
          }
        }
      }
  }
  /**
   * Yan_ice: mark.
   * Handle an incoming socket message.
   * @param data
   * @private
   */
  _handleMessage(packet, command, params) {
    switch (command) {
      case "getGamestate":
        this.sendGamestate(params);
        break;
      case "edition":
        this._updateEdition(params);
        break;
      case "fabled":
        this._updateFabled(params);
        break;
      case "gs":
        this._updateGamestate(params);
        break;
      case "player":
        this._updatePlayer(params);
        break;
      case "claim":
        this._updateSeat(params);
        break;
      case "ping":
        this._handlePing(params);
        break;
      case "nomination":
        if (!this._isSpectator) return;
        if (!params) {
          // create vote history record
          this._store.commit(
            "session/addHistory",
            this._store.state.players.players,
          );
        }
        this._store.commit("session/nomination", { nomination: params });
        break;
      case "swap":
        if (!this._isSpectator) return;
        this._store.commit("players/swap", params);
        break;
      case "move":
        if (!this._isSpectator) return;
        this._store.commit("players/move", params);
        break;
      case "remove":
        if (!this._isSpectator) return;
        this._store.commit("players/remove", params);
        break;
      case "marked":
        if (!this._isSpectator) return;
        this._store.commit("session/setMarkedPlayer", params);
        break;
      case "isNight":
        if (!this._isSpectator) return;
        this._store.commit("toggleNight", params);
        break;
      case "isVoteHistoryAllowed":
        if (!this._isSpectator) return;
        this._store.commit("session/setVoteHistoryAllowed", params);
        this._store.commit("session/clearVoteHistory");
        break;
      case "votingSpeed":
        if (!this._isSpectator) return;
        this._store.commit("session/setVotingSpeed", params);
        break;
      case "clearVoteHistory":
        if (!this._isSpectator) return;
        this._store.commit("session/clearVoteHistory");
        break;
      case "isVoteInProgress":
        if (!this._isSpectator) return;
        this._store.commit("session/setVoteInProgress", params);
        break;
      case "vote":
        this._handleVote(params);
        break;
      case "lock":
        this._handleLock(params);
        break;
      case "bye":
        this._handleBye(params);
        break;
      case "pronouns":
        this._updatePlayerPronouns(params);
        break;
      case "speaking":
        {
          this._store.commit("players/speak", 
            {
              idx: params[0],
              value: params[1]
            }
          );
        }
        break;

    }
  }



  /**
   * Connect to a new live session, either as host or spectator.
   * Set a unique playerId if there isn't one yet.
   * @param sessionID
   */
  connect(sessionID) {

    if (!this._store.state.loginbackend.playerId) {
      alert("error.");
      //this.login();
    }else{
      this._pings = {};
      this._store.commit("session/setPlayerCount", 0);
      this._store.commit("session/setPing", 0);
      this._isSpectator = this._store.state.session.isSpectator;

      this._isSpectator = true;
      this._open(sessionID);
    }
  }

  xjoinSession(sessionID) {
    const packet = new CommandPacket("sessionset", sessionID);
    packet.sender = this._store.state.loginbackend.playerId;
    packet.addCommand("join","roompwd");
    this._sendPacket(packet);
  }
  xleaveSession() {
    const packet = new CommandPacket("sessionset", '');
    packet.sender = this._store.state.loginbackend.playerId;
    packet.addCommand("leave","-");
    this._sendPacket(packet);
  }
  /**
   * Close the current session, if any.
   */
  disconnect() {
    this._pings = {};
    this._store.commit("session/setPlayerCount", 0);
    this._store.commit("session/setPing", 0);
    this._store.commit("session/setReconnecting", false);
    clearTimeout(this._reconnectTimer);
    if (this._socket) {
      if (this._isSpectator) {
        this._sendDirect("sessionset", "bye", this._store.state.loginbackend.playerId);
      }
      this._socket.close(1000);
      this._socket = null;
    }
  }

  /**
   * Publish the current gamestate.
   * Optional param to reduce traffic. (send only player data)
   * @param playerId
   * @param isLightweight
   */
  sendGamestate(playerId = "", isLightweight = false) {
    if (this._isSpectator) return;
    this._gamestate = this._store.state.players.players.map((player) => ({
      name: player.name,
      id: player.id,
      isDead: player.isDead,
      isVoteless: player.isVoteless,
      pronouns: player.pronouns,
      ...(player.role && player.role.team === "traveler"
        ? { roleId: player.role.id }
        : {}),
    }));
    if (isLightweight) {
      this._sendDirect(playerId, "gs", {
        gamestate: this._gamestate,
        isLightweight,
      });
    } else {
      const { session, grimoire } = this._store.state;
      const { fabled } = this._store.state.players;
      this.sendEdition(playerId);
      this._sendDirect(playerId, "gs", {
        gamestate: this._gamestate,
        isNight: grimoire.isNight,
        isVoteHistoryAllowed: session.isVoteHistoryAllowed,
        nomination: session.nomination,
        votingSpeed: session.votingSpeed,
        lockedVote: session.lockedVote,
        isVoteInProgress: session.isVoteInProgress,
        markedPlayer: session.markedPlayer,
        fabled: fabled.map((f) => (f.isCustom ? f : { id: f.id })),
        ...(session.nomination ? { votes: session.votes } : {}),
      });
    }
  }

  /**
   * Update the gamestate based on incoming data.
   * @param data
   * @private
   */
  _updateGamestate(data) {
    if (!this._isSpectator) return;
    const {
      gamestate,
      isLightweight,
      isNight,
      isVoteHistoryAllowed,
      nomination,
      votingSpeed,
      votes,
      lockedVote,
      isVoteInProgress,
      markedPlayer,
      fabled,
    } = data;
    const players = this._store.state.players.players;
    // adjust number of players
    if (players.length < gamestate.length) {
      for (let x = players.length; x < gamestate.length; x++) {
        this._store.commit("players/add", gamestate[x].name);
      }
    } else if (players.length > gamestate.length) {
      for (let x = players.length; x > gamestate.length; x--) {
        this._store.commit("players/remove", x - 1);
      }
    }
    // update status for each player
    gamestate.forEach((state, x) => {
      const player = players[x];
      const { roleId } = state;
      // update relevant properties
      ["name", "id", "isDead", "isVoteless", "pronouns"].forEach((property) => {
        const value = state[property];
        if (player[property] !== value) {
          this._store.commit("players/update", { player, property, value });
        }
      });
      // roles are special, because of travelers
      if (roleId && player.role.id !== roleId) {
        const role =
          this._store.state.roles.get(roleId) ||
          this._store.getters.rolesJSONbyId.get(roleId);
        if (role) {
          this._store.commit("players/update", {
            player,
            property: "role",
            value: role,
          });
        }
      } else if (!roleId && player.role.team === "traveler") {
        this._store.commit("players/update", {
          player,
          property: "role",
          value: {},
        });
      }
    });
    if (!isLightweight) {
      this._store.commit("toggleNight", !!isNight);
      this._store.commit("session/setVoteHistoryAllowed", isVoteHistoryAllowed);
      this._store.commit("session/nomination", {
        nomination,
        votes,
        votingSpeed,
        lockedVote,
        isVoteInProgress,
      });
      this._store.commit("session/setMarkedPlayer", markedPlayer);
      this._store.commit("players/setFabled", {
        fabled: fabled.map((f) => this._store.state.fabled.get(f.id) || f),
      });
    }
  }

  /**
   * Publish an edition update. ST only
   * @param playerId
   */
  sendEdition(playerId = "") {
    if (this._isSpectator) return;
    const { edition } = this._store.state;
    let roles;
    if (!edition.isOfficial) {
      roles = this._store.getters.customRolesStripped;
    }
    this._sendDirect(playerId, "edition", {
      edition: edition.isOfficial ? { id: edition.id } : edition,
      ...(roles ? { roles } : {}),
    });
  }

  /**
   * Update edition and roles for custom editions.
   * @param edition
   * @param roles
   * @private
   */
  _updateEdition({ edition, roles }) {
    if (!this._isSpectator) return;
    this._store.commit("setEdition", edition);
    if (roles) {
      this._store.commit("setCustomRoles", roles);
      if (this._store.state.roles.size !== roles.length) {
        const missing = [];
        roles.forEach(({ id }) => {
          if (!this._store.state.roles.get(id)) {
            missing.push(id);
          }
        });
        alert(
          `This session contains custom characters that can't be found. ` +
            `Please load them before joining! ` +
            `Missing roles: ${missing.join(", ")}`,
        );
        //this.disconnect();
        this._store.commit("toggleModal", "edition");
      }
    }
  }

  /**
   * Publish a fabled update. ST only
   */
  sendFabled() {
    if (this._isSpectator) return;
    const { fabled } = this._store.state.players;
    this._send(
      "fabled",
      fabled.map((f) => (f.isCustom ? f : { id: f.id })),
    );
  }

  /**
   * Update fabled roles.
   * @param fabled
   * @private
   */
  _updateFabled(fabled) {
    if (!this._isSpectator) return;
    this._store.commit("players/setFabled", {
      fabled: fabled.map((f) => this._store.state.fabled.get(f.id) || f),
    });
  }

  /**
   * Publish a player update.
   * @param player
   * @param property
   * @param value
   */
  sendPlayer({ player, property, value }) {
    if (this._isSpectator || property === "reminders") return;
    const index = this._store.state.players.players.indexOf(player);
    if (property === "role") {
      if (value.team && value.team === "traveler") {
        // update local gamestate to remember this player as a traveler
        this._gamestate[index].roleId = value.id;
        this._send("player", {
          index,
          property,
          value: value.id,
        });
      } else if (this._gamestate[index].roleId) {
        // player was previously a traveler
        delete this._gamestate[index].roleId;
        this._send("player", { index, property, value: "" });
      }
    } else {
      this._send("player", { index, property, value });
    }
  }

  /**
   * Update a player based on incoming data. Player only.
   * @param index
   * @param property
   * @param value
   * @private
   */
  _updatePlayer({ index, property, value }) {
    if (!this._isSpectator) return;
    const player = this._store.state.players.players[index];
    if (!player) return;
    // special case where a player stops being a traveler
    if (property === "role") {
      if (!value && player.role.team === "traveler") {
        // reset to an unknown role
        this._store.commit("players/update", {
          player,
          property: "role",
          value: {},
        });
      } else {
        // load role, first from session, the global, then fail gracefully
        const role =
          this._store.state.roles.get(value) ||
          this._store.getters.rolesJSONbyId.get(value) ||
          {};
        this._store.commit("players/update", {
          player,
          property: "role",
          value: role,
        });
      }
    } else {
      // just update the player otherwise
      this._store.commit("players/update", { player, property, value });
    }
  }

  /**
   * Publish a player pronouns update
   * @param player
   * @param value
   * @param isFromSockets
   */
  sendPlayerPronouns({ player, value, isFromSockets }) {
    //send pronoun only for the seated player or storyteller
    //Do not re-send pronoun data for an update that was recieved from the sockets layer
    if (
      isFromSockets ||
      (this._isSpectator && this._store.state.loginbackend.playerId !== player.id)
    )
      return;
    const index = this._store.state.players.players.indexOf(player);
    this._send("pronouns", [index, value]);
  }

  /**
   * Update a pronouns based on incoming data.
   * @param index
   * @param value
   * @private
   */
  _updatePlayerPronouns([index, value]) {
    const player = this._store.state.players.players[index];

    this._store.commit("players/update", {
      player,
      property: "pronouns",
      value,
      isFromSockets: true,
    });
  }

  /**
   * Handle a ping message by another player / storyteller
   * @param playerIdOrCount
   * @param latency
   * @private
   */
  _handlePing([playerIdOrCount = 0, latency] = []) {
    const now = new Date().getTime();
    if (!this._isSpectator) {
      // remove players that haven't sent a ping in twice the timespan
      for (let player in this._players) {
        if (now - this._players[player] > this._pingInterval * 2) {
          delete this._players[player];
          delete this._pings[player];
        }
      }
      // remove claimed seats from players that are no longer connected
      this._store.state.players.players.forEach((player) => {
        if (player.id && !this._players[player.id]) {
          this._store.commit("players/update", {
            player,
            property: "id",
            value: "",
          });
        }
      });
      // store new player data
      if (playerIdOrCount) {
        this._players[playerIdOrCount] = now;
        const ping = parseInt(latency, 10);
        if (ping && ping > 0 && ping < 30 * 1000) {
          // ping to Players
          this._pings[playerIdOrCount] = ping;
          const pings = Object.values(this._pings);
          this._store.commit(
            "session/setPing",
            Math.round(pings.reduce((a, b) => a + b, 0) / pings.length),
          );
        }
      }
    } else if (latency) {
      // ping to ST
      this._store.commit("session/setPing", parseInt(latency, 10));
    }
    // update player count
    if (!this._isSpectator || playerIdOrCount) {
      this._store.commit(
        "session/setPlayerCount",
        this._isSpectator ? playerIdOrCount : Object.keys(this._players).length,
      );
    }
  }

  /**
   * Handle a player leaving the sessions. ST only
   * @param playerId
   * @private
   */
  _handleBye(playerId) {
    if (this._isSpectator) return;
    delete this._players[playerId];
    this._store.commit(
      "session/setPlayerCount",
      Object.keys(this._players).length,
    );
  }

  /**
   * Claim a seat, needs to be confirmed by the Storyteller.
   * Seats already occupied can't be claimed.
   * @param seat either -1 to vacate or the index of the seat claimed
   */
  claimSeat(seat) {
    if (!this._isSpectator) return;
    const packet = new CommandPacket("sessionset");
    packet.addCommand("claimseat",seat);
    this._sendPacket(packet);
    // const players = this._store.state.players.players;
    // if (players.length > seat && (seat < 0 || !players[seat].id)) {
    //   this._send("claim", [seat, this._store.state.loginbackend.playerId]);
    // }
  }

  /**
   * Update a player id associated with that seat.
   * @param index seat index or -1
   * @param value playerId to add / remove
   * @private
   */
  _updateSeat([index, value]) {
    if (this._isSpectator) return;
    const property = "id";
    const players = this._store.state.players.players;
    // remove previous seat
    const oldIndex = players.findIndex(({ id }) => id === value);
    if (oldIndex >= 0 && oldIndex !== index) {
      this._store.commit("players/update", {
        player: players[oldIndex],
        property,
        value: "",
      });
    }
    // add playerId to new seat
    if (index >= 0) {
      const player = players[index];
      if (!player) return;
      this._store.commit("players/update", { player, property, value });
    }
    // update player session list as if this was a ping
    this._handlePing([true, value, 0]);
  }

  /**
   * Distribute player roles to all seated players in a direct message.
   * This will be split server side so that each player only receives their own (sub)message.
   */
  distributeRoles() {
    if (this._isSpectator) return;
    const message = {};
    this._store.state.players.players.forEach((player, index) => {
      if (player.id && player.role) {
        message[player.id] = [
          "player",
          { index, property: "role", value: player.role.id },
        ];
      }
    });
    if (Object.keys(message).length) {
      this._send("direct", message);
    }
  }

  /**
   * A player nomination. ST only
   * This also syncs the voting speed to the players.
   * Payload can be an object with {nomination} property or just the nomination itself, or undefined.
   * @param payload [nominator, nominee]|{nomination}
   */
  nomination(payload) {
    if (this._isSpectator) return;
    const nomination = payload ? payload.nomination || payload : payload;
    const players = this._store.state.players.players;
    if (
      !nomination ||
      (players.length > nomination[0] && players.length > nomination[1])
    ) {
      this.setVotingSpeed(this._store.state.session.votingSpeed);
      this._send("nomination", nomination);
    }
  }

  /**
   * Send a vote. Player or ST
   * @param index Seat of the player
   * @param sync Flag whether to sync this vote with others or not
   */
  vote([index]) {
    const player = this._store.state.players.players[index];
    if (
      this._store.state.loginbackend.playerId === player.id ||
      !this._isSpectator
    ) {
      // send vote only if it is your own vote or you are the storyteller
      this._send("vote", [
        index,
        this._store.state.session.votes[index],
        !this._isSpectator,
      ]);
    }
  }

  /**
   * Handle an incoming vote, but only if it is from ST or unlocked.
   * @param index
   * @param vote
   * @param fromST
   */
  _handleVote([index, vote, fromST]) {
    const { session, players } = this._store.state;
    const playerCount = players.players.length;
    const indexAdjusted =
      (index - 1 + playerCount - session.nomination[1]) % playerCount;
    if (fromST || indexAdjusted >= session.lockedVote - 1) {
      this._store.commit("session/vote", [index, vote]);
    }
  }

  /**
   * Lock a vote. ST only
   */
  lockVote() {
    if (this._isSpectator) return;
    const { lockedVote, votes, nomination } = this._store.state.session;
    const { players } = this._store.state.players;
    const index = (nomination[1] + lockedVote - 1) % players.length;
    this._send("lock", [this._store.state.session.lockedVote, votes[index]]);
  }

  setSpeaking(isspeaking) { // todo: send speaking to host

    const players = this._store.state.players.players;
    for(let a = 0;a<players.length;a++){
      if(players[a].id == this._store.state.loginbackend.playerId) {
        this._sendDirect("host", "speaking", [a, isspeaking]);
      }
    }
  }
  /**
   * Update vote lock and the locked vote, if it differs. Player only
   * @param lock
   * @param vote
   * @private
   */
  _handleLock([lock, vote]) {
    if (!this._isSpectator) return;
    this._store.commit("session/lockVote", lock);
    if (lock > 1) {
      const { lockedVote, nomination } = this._store.state.session;
      const { players } = this._store.state.players;
      const index = (nomination[1] + lockedVote - 1) % players.length;
      if (this._store.state.session.votes[index] !== vote) {
        this._store.commit("session/vote", [index, vote]);
      }
    }
  }

    /**
     * Send a CommandPacket through the socket.
     * @param command
     * @param params
     * @private
    */
  _sendPacket(packet) {
      console.log("packet", packet);
      const sessionId = this._store.state.loginbackend.sessionId;
      packet.session = sessionId;
      if (this._socket && this._socket.readyState == 1) {
        this._socket.send(packet.serialize());
      }
  }

  /**
   * ST boardcast the action
   * @param payload
   */
  requestSync(type, payload) {
    if (this._isSpectator) return;
    const packet = new CommandPacket("sync");
    packet.addCommand(type, payload);
    this._sendPacket(packet);
  }

  /**
   * Player sync the action
   * @param payload
   */
  _handleSync(packet, type, payload) {
    if (!this._isSpectator) return;
    this._store.commit(type, payload);
  }

  /**
   * Kick a player. ST only
   * @param payload
   */
  kickPlayer(idx) {
        if (this._isSpectator) return;
    const playersls = this._store.state.players.players;
    const packet = new CommandPacket("sessionset");
    packet.addCommand("kick", playersls[idx].id);
    this._sendPacket(packet);
  }
}


export default (store) => {
  // setup
  const session = new LiveSession(store);

  // listen to mutations
  store.subscribe(({ type, payload }, state) => {
    switch (type) {
      case "loginbackend/loginWithData":
        session.login(payload.username, payload.password);
        break;
      case "loginbackend/loginWithToken":
        session.login('', payload.playerId);
        break;
      case "loginbackend/setSessionId":
        if (state.loginbackend.sessionId) {
          session.xjoinSession(state.loginbackend.sessionId);
        } else{
          session.xleaveSession();
        }
        break;
      case "session/claimSeat":
        //session.claimSeat(payload);
        //session.requestSync(type, payload);
        break;
      case "players/kick":
        session.kickPlayer(payload);
        break;
      case "players/remove":
        session.requestSync(type, payload);
        break;
      case "session/distributeRoles":
        if (payload) {
          session.distributeRoles();
        }
        break;
      case "session/nomination":
      case "session/setNomination":
      case "session/setVoteInProgress":
      case "session/setVotingSpeed":
      case "toggleNight":
      case "session/setVoteHistoryAllowed":
      case "session/setMarkedPlayer":
      case "players/speak":
      case "players/swap":
      case "players/move":
      case "session/clearVoteHistory":
        session.requestSync(type, payload);
        break;
      case "session/sendCommand":
        session._sendPacket(payload);
        break;
      case "loginbackend/setPlayerIsSpeaking":
        session.setSpeaking(payload);
        break

      case "session/voteSync":
        //session.sync_mutation(type, payload);
        session.vote(payload);
        break;
      case "session/lockVote":
        session.lockVote();
        break;

      case "setEdition":
        //session.sync_mutation(type, payload);
        session.sendEdition();
        break;
      case "players/setFabled":
        //session.sync_mutation(type, payload);
        session.sendFabled();
        break;
      case "players/set":
      case "players/clear":
      case "players/add":
        session.sendGamestate("", true);
        break;
      case "players/update":
        if (payload.property === "pronouns") {
          session.sendPlayerPronouns(payload);
        } else {
          session.sendPlayer(payload);
        }
        break;
    }
  });

};

const NEWPLAYER = {
  name: "",
  id: "",
  role: {},
  reminders: [],
  isVoteless: false,
  isTalking: null,
  isDead: false,
  pronouns: "",
};

const state = () => ({
  players: [],
  fabled: [],
  bluffs: [],
});

const getters = {
  alive({ players }) {
    return players.filter((player) => !player.isDead).length;
  },
  nonTravelers({ players }) {
    const nonTravelers = players.filter(
      (player) => player.role.team !== "traveler",
    );
    return Math.min(nonTravelers.length, 15);
  },
  // calculate a Map of player => night order
  nightOrder({ players, fabled }) {
    const firstNight = [0];
    const otherNight = [0];
    players.forEach(({ role }) => {
      if (role.firstNight && !firstNight.includes(role.firstNight)) {
        firstNight.push(role.firstNight);
      }
      if (role.otherNight && !otherNight.includes(role.otherNight)) {
        otherNight.push(role.otherNight);
      }
    });
    fabled.forEach((role) => {
      if (role.firstNight && !firstNight.includes(role.firstNight)) {
        firstNight.push(role.firstNight);
      }
      if (role.otherNight && !otherNight.includes(role.otherNight)) {
        otherNight.push(role.otherNight);
      }
    });
    firstNight.sort((a, b) => a - b);
    otherNight.sort((a, b) => a - b);
    const nightOrder = new Map();
    players.forEach((player) => {
      const first = Math.max(firstNight.indexOf(player.role.firstNight), 0);
      const other = Math.max(otherNight.indexOf(player.role.otherNight), 0);
      nightOrder.set(player, { first, other });
    });
    fabled.forEach((role) => {
      const first = Math.max(firstNight.indexOf(role.firstNight), 0);
      const other = Math.max(otherNight.indexOf(role.otherNight), 0);
      nightOrder.set(role, { first, other });
    });
    return nightOrder;
  },
};

const actions = {
  randomize({ state, commit }) {
    const players = state.players
      .map((a) => [Math.random(), a])
      .sort((a, b) => a[0] - b[0])
      .map((a) => a[1]);
    commit("set", players);
  },
  clearRoles({ state, commit, rootState }) {
    let players;
    if (rootState.session.isSpectator) {
      players = state.players.map((player) => {
        if (player.role.team !== "traveler") {
          player.role = {};
        }
        player.reminders = [];
        return player;
      });
    } else {
      players = state.players.map(({ name, id, pronouns }) => ({
        ...NEWPLAYER,
        name,
        id,
        pronouns,
      }));
      commit("setFabled", { fabled: [] });
    }
    commit("set", players);
    commit("setBluff");
  },
};

const mutations = {
  clear(state) {
    state.players = [];
    state.bluffs = [];
    state.fabled = [];
  },
  set(state, players = []) {
    state.players = players;
  },
  /**
  The update mutation also has a property for isFromSockets
  this property can be addded to payload object for any mutations
  then can be used to prevent infinite loops when a property is
  able to be set from multiple different session on websockets.
  An example of this is in the sendPlayerPronouns and _updatePlayerPronouns
  in socket.js.
   */
  update(state, { player, property, value }) {
    const index = state.players.indexOf(player);
    if (index >= 0) {
      state.players[index][property] = value;
    }
  },

  add(state) {
    state.players.push({
      name: "---",
      id: "",
      role: {},
      reminders: [],
      isVoteless: false,
      isDead: false,
      pronouns: "",
    });
  },
  kick(state, idx) {
    const player = state.players[idx];
    player.name = '---';
    //nothing here, only for subscribe
  },
  speak(state, {idx, value}) {
    if(value){
      const player = state.players[idx];

      if (player.isTalking) {
        clearTimeout(player.isTalking);
      }

      player.isTalking = setTimeout(() => {
        player.isTalking = null;
      }, 1500);
    }

    //nothing here, only for subscribe
  },
  remove(state, index) {
    state.players.splice(index, 1);
  },
  swap(state, [from, to]) {
    [state.players[from], state.players[to]] = [
      state.players[to],
      state.players[from],
    ];
    // hack: "modify" the array so that Vue notices something changed
    state.players.splice(0, 0);
  },
  move(state, [from, to]) {
    state.players.splice(to, 0, state.players.splice(from, 1)[0]);
  },
  setBluff(state, { index, role } = {}) {
    if (index !== undefined) {
      state.bluffs.splice(index, 1, role);
    } else {
      state.bluffs = [];
    }
  },
  setFabled(state, { index, fabled } = {}) {
    if (index !== undefined) {
      state.fabled.splice(index, 1);
    } else if (fabled) {
      if (!Array.isArray(fabled)) {
        state.fabled.push(fabled);
      } else {
        state.fabled = fabled;
      }
    }
  },
};

export default {
  namespaced: true,
  state,
  getters,
  actions,
  mutations,
};

class CommandPacket {
  constructor(header = "", session = "") {
    this.header = header;
    this.session = session;
    this.sender = "";
    this.receiver = "";
    this.commands = [];

    //this.sender_socket = ''; //should be filled immediately after deserializing.
  }

  addCommand(cmd, param) {
    this.commands.push({ cmd, param });
  }

  serialize() {
    return JSON.stringify({
      header: this.header,
      session: this.session,
      commands: this.commands,
      sender: this.sender,
      receiver: this.receiver,
    });
  }

  forEachCommand(callback){
    this.commands.forEach((block) => {
          callback(this, block['cmd'], block['param']);
      });
  }

  static deserialize(jsonStr) {
    try {
      const obj = JSON.parse(jsonStr);
      const packet = new CommandPacket(obj.header, obj.session);
      packet.sender = obj.sender;
      packet.receiver = obj.receiver;
      if (Array.isArray(obj.commands)) {
        packet.commands = obj.commands;
      }
      return packet;
    } catch (e) {
      console.error("反序列化失败:", e);
      return null;
    }
  }

}

module.exports = CommandPacket;

import io from "socket.io-client";
import * as mediasoupClient from 'mediasoup-client';
import store from "@/store";

class MediasoupRoom {
  constructor() {
    this.socket = null;
    this.device = null;
    this.sendTransport = null;
    this.recvTransport = null;
    this.joined = false;

    this.roomId = null;
    this.userId = null;

    this.stream = null;        // 本地音频流
    this.producer = null;      // 发送的producer

    // 音量检测相关
    this.audioContext = null;
    this.analyser = null;
    this.microphoneSource = null;
    this.volume = 0;           // 实时音量 0~1
    this.loud_keep = 0;
    this.volumeThreshold = 0.1;
    this.volumeCallback = this._volumeCallback.bind(this);
    this.volumeMonitorId = null;
  }

  _volumeCallback(loud) {
    if(store.state.loginbackend.isSpeaking != loud) {
      if(loud) {
        store.commit("loginbackend/setPlayerIsSpeaking", 
        loud
        );
        this.loud_keep = 60;
      }
    }
    if(loud && this.loud_keep > 0) {
      this.loud_keep--;
      if(this.loud_keep == 0){
        store.commit("loginbackend/setPlayerIsSpeaking", 
        loud
        );
        this.loud_keep = 60;
      }
    }
  }

  async promise_request(request, params) {
    return new Promise((resolve) => {
      this.socket.emit(request, params, resolve);
    });
  }

  async joinRoom(roomId, userId) {
    if (this.joined) {
      console.warn("Already joined");
      return;
    }
    this.roomId = roomId;
    this.userId = userId;
    this.serverURL = store.state.loginbackend.vocalServer;

    this.socket = io(this.serverURL, { timeout: 5000, reconnection: false });

    this.device = new mediasoupClient.Device();

    this.socket.on("newProducer", ({ producerId }) => {
      this.consume(producerId);
    });
    this.socket.on("connect_error", () => {
      alert("无法连接至语音服务器：状态异常。")
      this.socket = null;
      this.device = null;
      this.joined = false;
      this.sendTransport = null;
      this.recvTransport = null;
    });

    this.socket.on("disconnect", (reason) => {
      console.warn("连接断开", reason);
      this.socket = null;
      this.device = null;
      this.joined = false;
      this.sendTransport = null;
      this.recvTransport = null;
    });

    const {
      routerRtpCapabilities,
      sendTransportOptions,
      recvTransportOptions,
    } = await this.promise_request("initializeTalk", { roomId, userId });

    await this.device.load({ routerRtpCapabilities });

    this.sendTransport = this.device.createSendTransport(sendTransportOptions);
    this.recvTransport = this.device.createRecvTransport(recvTransportOptions);

    // 连接 sendTransport
    this.sendTransport.on("connect", ({ dtlsParameters }, callback) => {
      this.socket.emit("transport-connect", { transportId: this.sendTransport.id, dtlsParameters });
      callback();
    });
    // 连接 recvTransport
    this.recvTransport.on("connect", ({ dtlsParameters }, callback) => {
      this.socket.emit("transport-connect", { transportId: this.recvTransport.id, dtlsParameters });
      callback();
    });

    // produce 事件
    this.sendTransport.on("produce", ({ kind, rtpParameters }, callback) => {
      this.socket.emit("produce", {
        transportId: this.sendTransport.id,
        kind,
        rtpParameters,
      }, ({ id }) => {
        callback({ id });
      });
    });

    const { existingProducers } = await this.promise_request("startTalk", {
      roomId,
      rtpCapabilities: this.device.rtpCapabilities,
    });

    // 获取音频流并produce
    this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const track = this.stream.getAudioTracks()[0];
    this.producer = await this.sendTransport.produce({ track });

    // 启动音量检测
    this.startVolumeMonitor(this.stream);

    // 消费其他producer
    for (const producerId of existingProducers) {
      this.consume(producerId);
    }

    this.joined = true;
  }

  async consume(producerId) {
    this.socket.emit("consume", {
      producerId,
      rtpCapabilities: this.device.rtpCapabilities
    }, async (consumerParameters) => {
      if (consumerParameters.error) {
        console.warn("consume error:", consumerParameters.error);
        return;
      }
      const consumer = await this.recvTransport.consume({
        id: consumerParameters.id,
        producerId: consumerParameters.producerId,
        kind: consumerParameters.kind,
        rtpParameters: consumerParameters.rtpParameters,
      });
      const remoteStream = new MediaStream();
      remoteStream.addTrack(consumer.track);

      // 这里可自行设计播放方案，比如触发事件或调用回调
      const audio = new Audio();
      audio.srcObject = remoteStream;
      audio.autoplay = true;
      audio.play().catch(e => console.warn("Audio play error:", e));
    });
  }

  async leaveRoom() {
    if (!this.joined) return;

    if (this.producer) {
      await this.producer.close();
      this.producer = null;
    }
    if (this.sendTransport) {
      this.sendTransport.close();
      this.sendTransport = null;
    }
    if (this.recvTransport) {
      this.recvTransport.close();
      this.recvTransport = null;
    }
    if (this.stream) {
      this.stream.getTracks().forEach(t => t.stop());
      this.stream = null;
    }
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
    }

    this.stopVolumeMonitor();

    this.joined = false;
    this.roomId = null;
    this.userId = null;
  }

  mute() {
    if (!this.stream) return;
    this.stream.getAudioTracks().forEach(track => track.enabled = false);
  }

  unmute() {
    if (!this.stream) return;
    this.stream.getAudioTracks().forEach(track => track.enabled = true);
  }

  startVolumeMonitor(stream) {
    if (!this.audioContext) {
      this.audioContext = new AudioContext();
    }
    this.microphoneSource = this.audioContext.createMediaStreamSource(stream);
    this.analyser = this.audioContext.createAnalyser();
    this.analyser.fftSize = 512;

    this.microphoneSource.connect(this.analyser);

    const dataArray = new Uint8Array(this.analyser.frequencyBinCount);

    const updateVolume = () => {
      this.analyser.getByteFrequencyData(dataArray);
      let values = 0;
      for (let i = 0; i < dataArray.length; i++) {
        values += dataArray[i];
      }
      const average = values / dataArray.length;
      this.volume = average / 255;

      if (this.volumeCallback) {
        this.volumeCallback(this.volume >= this.volumeThreshold);
      }
      this.volumeMonitorId = requestAnimationFrame(updateVolume);
    };

    updateVolume();
  }

  stopVolumeMonitor() {
    if (this.volumeMonitorId) {
      cancelAnimationFrame(this.volumeMonitorId);
      this.volumeMonitorId = null;
    }
    if (this.microphoneSource) {
      this.microphoneSource.disconnect();
      this.microphoneSource = null;
    }
    if (this.analyser) {
      this.analyser.disconnect();
      this.analyser = null;
    }
    if (this.audioContext) {
      this.audioContext.close();
      this.audioContext = null;
    }
  }
}

const mediasoupRoom = new MediasoupRoom();

export default mediasoupRoom;
